test('invoiceTotals: calculates subtotal and total for single line', () => {
  const invoice = {
    lines: [{ qty: 8, unitPrice: 9500 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 76000);
  assert.equal(result.value.total, 76000);
});

test('invoiceTotals: calculates subtotal and total for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 1, unitPrice: 120000 },
      { qty: 100, unitPrice: 37 },
    ],
