  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 0);
  assert.equal(result.value.total, 0);
});

test('invoiceTotals: works with real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const totalsResult = invoiceTotals(invoice);

